function governanceFlow(request, policy){
  const subs = decompose(request);
  const guarded = subs.map(s => injectGuard(s, policy));
  const finalOut = assemble(guarded);
  const audit = {tenant: policy.tenant, ts: Date.now(), steps: subs.length};
  return {finalOut, audit};
}
